begin
  if (select count(*) from clube_novo.tecnico_jogo) <> 1594 then
    raise exception 'preflight: tecnico_jogo não tem 1.594 linhas';
  end if;
  if (select count(*) from clube_novo.tecnico_jogo where fonte_autoritativa='dt870_updated') <> 1478 then
    raise exception 'preflight: técnicos atuais não totalizam 1.478';
  end if;
  if (select count(*) from stage_tecnico_apresentacao) <> 1478 then
    raise exception 'preflight: stage de técnicos não tem 1.478 linhas';
  end if;
  if (select count(*) from stage_nacionalidade) <> 214 then
    raise exception 'preflight: catálogo de nacionalidades não tem 214 linhas';
  end if;
  if (select count(*) from stage_afinidade) <> 8 then
    raise exception 'preflight: catálogo de afinidades não tem 8 linhas';
  end if;
  if exists (
    select 1 from stage_tecnico_apresentacao s
    left join clube_novo.tecnico_jogo t on t.id=s.id
    where t.id is null or t.fonte_autoritativa <> 'dt870_updated'
       or t.registro_dt870_atualizacao <> s.registro
       or t.hash_coach_bin <> s.hash_coach_bin
  ) then raise exception 'preflight: pacote não corresponde ao Coach.bin atual do banco'; end if;
  if exists (
    select 1 from clube_novo.tecnico_jogo t
    left join stage_tecnico_apresentacao s on s.id=t.id
    where t.fonte_autoritativa='dt870_updated' and s.id is null
  ) then raise exception 'preflight: técnico atual ausente do pacote'; end if;
  if exists (select 1 from stage_tecnico_apresentacao where idade not between 14 and 141 or codigo_afinidade not between 0 and 7) then
    raise exception 'preflight: idade ou afinidade fora do domínio físico';
  end if;
  if exists (select 1 from stage_tecnico_apresentacao s left join stage_nacionalidade n on n.codigo_jogo=s.codigo_nacionalidade where n.codigo_jogo is null) then
    raise exception 'preflight: nacionalidade órfã no pacote';
  end if;
  if exists (select 1 from stage_tecnico_apresentacao s left join stage_afinidade a on a.codigo_jogo=s.codigo_afinidade where a.codigo_jogo is null) then
    raise exception 'preflight: afinidade órfã no pacote';
  end if;
  if not exists (select 1 from stage_tecnico_apresentacao where id=17601312850052 and idade=44 and codigo_nacionalidade=215 and codigo_afinidade=5) then
    raise exception 'preflight: amostra Capello divergiu';
  end if;
end $$;

create table if not exists clube_novo.nacionalidade_jogo (
  codigo_jogo smallint primary key check (codigo_jogo between 0 and 511),
  nome_pt_br text not null,
  sigla text not null,
  arquivo text not null,
  cpk_origem text not null,
  fonte_autoritativa text not null,
  registro integer not null check (registro >= 0),
  tamanho_registro smallint not null check (tamanho_registro > 0),
  bit_codigo smallint not null check (bit_codigo >= 0),
  largura_codigo smallint not null check (largura_codigo > 0),
  offset_nome_pt_br integer not null check (offset_nome_pt_br >= 0),
  largura_nome_pt_br smallint not null check (largura_nome_pt_br > 0),
  codificacao_nome_pt_br text not null,
  offset_sigla integer not null check (offset_sigla >= 0),
  largura_sigla smallint not null check (largura_sigla > 0),
  hash_country_bin text not null,
  presente_dt200 boolean not null,
  presente_dt870_steam boolean not null,
  presente_dt870_atualizacao boolean not null,
  contrato_extracao text not null,
  pode_rodar boolean not null default false,
  falta_o_que text,
  carregado_em timestamptz not null default now()
);

create table if not exists clube_novo.afinidade_tecnico_jogo (
  codigo_jogo smallint primary key check (codigo_jogo between 0 and 7),
  nome_pt text,
  nome_tela text,
  ausencia_legitima boolean not null default false,
  rotulo_confirmado boolean not null default false,
  secao_texto text,
  id_texto integer,
  arquivo_fonte text not null,
  cpk_fonte text not null,
  bit smallint not null check (bit >= 0),
  largura smallint not null check (largura > 0),
  hash_coach_bin text not null,
  arquivo_texto text,
  cpk_texto text,
  hash_all_str text,
  presente_dt870_atualizacao boolean not null,
  contrato_extracao text not null,
  pode_rodar boolean not null default false,
  falta_o_que text,
  carregado_em timestamptz not null default now(),
  check ((codigo_jogo=0) = ausencia_legitima),
  check (not rotulo_confirmado or (nome_pt is not null and nome_tela is not null and secao_texto is not null and id_texto is not null)),
  check (rotulo_confirmado or (nome_pt is null and nome_tela is null and secao_texto is null and id_texto is null))
);

alter table clube_novo.tecnico_jogo
  add column if not exists idade smallint,
  add column if not exists codigo_nacionalidade smallint,
  add column if not exists codigo_afinidade smallint,
  add column if not exists fonte_campos_apresentacao text,
  add column if not exists cpk_campos_apresentacao text,
  add column if not exists arquivo_campos_apresentacao text,
  add column if not exists registro_campos_apresentacao integer,
  add column if not exists hash_campos_apresentacao text,
  add column if not exists contrato_campos_apresentacao text,
  add column if not exists carregado_campos_apresentacao_em timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint where conname='tecnico_jogo_idade_check' and conrelid='clube_novo.tecnico_jogo'::regclass) then
    alter table clube_novo.tecnico_jogo add constraint tecnico_jogo_idade_check check (idade is null or idade between 14 and 141);
  end if;
  if not exists (select 1 from pg_constraint where conname='tecnico_jogo_codigo_nacionalidade_fkey' and conrelid='clube_novo.tecnico_jogo'::regclass) then
    alter table clube_novo.tecnico_jogo add constraint tecnico_jogo_codigo_nacionalidade_fkey foreign key (codigo_nacionalidade) references clube_novo.nacionalidade_jogo(codigo_jogo) on delete restrict;
  end if;
  if not exists (select 1 from pg_constraint where conname='tecnico_jogo_codigo_afinidade_fkey' and conrelid='clube_novo.tecnico_jogo'::regclass) then
    alter table clube_novo.tecnico_jogo add constraint tecnico_jogo_codigo_afinidade_fkey foreign key (codigo_afinidade) references clube_novo.afinidade_tecnico_jogo(codigo_jogo) on delete restrict;
  end if;
  if not exists (select 1 from pg_constraint where conname='tecnico_jogo_campos_apresentacao_completos_check' and conrelid='clube_novo.tecnico_jogo'::regclass) then
    alter table clube_novo.tecnico_jogo add constraint tecnico_jogo_campos_apresentacao_completos_check check (
      (idade is null and codigo_nacionalidade is null and codigo_afinidade is null
       and fonte_campos_apresentacao is null and cpk_campos_apresentacao is null
       and arquivo_campos_apresentacao is null and registro_campos_apresentacao is null
       and hash_campos_apresentacao is null and contrato_campos_apresentacao is null
       and carregado_campos_apresentacao_em is null)
      or
      (idade is not null and codigo_nacionalidade is not null and codigo_afinidade is not null
       and fonte_campos_apresentacao is not null and cpk_campos_apresentacao is not null
       and arquivo_campos_apresentacao is not null and registro_campos_apresentacao is not null
       and hash_campos_apresentacao is not null and contrato_campos_apresentacao is not null
       and carregado_campos_apresentacao_em is not null)
    );
  end if;
end $$;

create index if not exists tecnico_jogo_codigo_nacionalidade_idx on clube_novo.tecnico_jogo(codigo_nacionalidade);
create index if not exists tecnico_jogo_codigo_afinidade_idx on clube_novo.tecnico_jogo(codigo_afinidade);

