set idade=s.idade,
    codigo_nacionalidade=s.codigo_nacionalidade,
    codigo_afinidade=s.codigo_afinidade,
    fonte_campos_apresentacao='dt870_updated',
    cpk_campos_apresentacao='dt870_console_win.cpk',
    arquivo_campos_apresentacao='Coach.bin',
    registro_campos_apresentacao=s.registro,
    hash_campos_apresentacao=s.hash_coach_bin,
