select assunto,cpk,arquivo,chave,endereco,registro,true,date '2026-08-28',observacao
from jsonb_to_recordset($map$[{"assunto":"tecnico.idade","cpk":"dt870_console_win.cpk (atualização)","arquivo":"Coach.bin","chave":"tecnico_jogo.id u64","endereco":"bit 231, largura 7","registro":"176 bytes; índice em tecnico_jogo.registro_campos_apresentacao","observacao":"idade = valor físico + 14; hash Coach.bin 092a07c62d1df0f19da6ad0e4e1252de07e5e1df8e9090760734829044c0d42a; clubef-coach-display-fields-extraction-v2"},{"assunto":"tecnico.nacionalidade","cpk":"dt870_console_win.cpk (atualização)","arquivo":"Coach.bin","chave":"tecnico_jogo.id u64 -> nacionalidade_jogo.codigo_jogo","endereco":"bit 170, largura 8","registro":"176 bytes; índice em tecnico_jogo.registro_campos_apresentacao","observacao":"código resolve em Country.bin; hash Coach.bin 092a07c62d1df0f19da6ad0e4e1252de07e5e1df8e9090760734829044c0d42a; clubef-coach-display-fields-extraction-v2"},{"assunto":"tecnico.afinidade","cpk":"dt870_console_win.cpk (atualização)","arquivo":"Coach.bin","chave":"tecnico_jogo.id u64 -> afinidade_tecnico_jogo.codigo_jogo","endereco":"bit 187, largura 3","registro":"176 bytes; índice em tecnico_jogo.registro_campos_apresentacao","observacao":"enum 0..7; código 0 é ausência legítima; hash Coach.bin 092a07c62d1df0f19da6ad0e4e1252de07e5e1df8e9090760734829044c0d42a; clubef-coach-display-fields-extraction-v2"},{"assunto":"nacionalidade.codigo","cpk":"DT200 + DT870 original + DT870 atualização (arquivo byte-idêntico)","arquivo":"Country.bin","chave":"nacionalidade_jogo.codigo_jogo","endereco":"bit 10, largura 9","registro":"1488 bytes; índice em nacionalidade_jogo.registro","observacao":"214 códigos únicos; hash Country.bin 6dcb876a1922281cc5bf513f8ee117846fbeed42e48936f40af2007232c1b0a7; clubef-coach-display-fields-extraction-v2"},{"assunto":"nacionalidade.nome_pt_br","cpk":"DT200 + DT870 original + DT870 atualização (arquivo byte-idêntico)","arquivo":"Country.bin","chave":"nacionalidade_jogo.codigo_jogo","endereco":"offset 788, largura máxima 70 bytes","registro":"texto UTF-8 terminado por NUL dentro do registro de 1488 bytes","observacao":"214 nomes sem órfão ou duplicidade; hash Country.bin 6dcb876a1922281cc5bf513f8ee117846fbeed42e48936f40af2007232c1b0a7; clubef-coach-display-fields-extraction-v2"},{"assunto":"nacionalidade.sigla","cpk":"DT200 + DT870 original + DT870 atualização (arquivo byte-idêntico)","arquivo":"Country.bin","chave":"nacionalidade_jogo.codigo_jogo","endereco":"offset 708, largura máxima 10 bytes","registro":"texto ASCII/UTF-8 terminado por NUL dentro do registro de 1488 bytes","observacao":"214 siglas; hash Country.bin 6dcb876a1922281cc5bf513f8ee117846fbeed42e48936f40af2007232c1b0a7; clubef-coach-display-fields-extraction-v2"},{"assunto":"afinidade_tecnico.rotulo.codigo_5","cpk":"dt261_bra_console_win.cpk","arquivo":"all.str","chave":"afinidade_tecnico_jogo.codigo_jogo=5","endereco":"seção Any1W, id_texto 495","registro":"texto oficial 'Jogadores de AT'; tela observada 'Atacantes'","observacao":"único vínculo código-rótulo promovido; demais códigos sem rótulo; hash all.str 306741adab8376ed64620b618ae9721d316ae548b126419730b9bd5ff5f525a9"}]$map$::jsonb)
  as x(assunto text,cpk text,arquivo text,chave text,endereco text,registro text,observacao text)
on conflict (assunto,arquivo) do update set
  cpk=excluded.cpk, chave=excluded.chave, endereco=excluded.endereco,
  registro=excluded.registro, aberto=excluded.aberto, medido_em=excluded.medido_em,
  observacao=excluded.observacao;

comment on table clube_novo.nacionalidade_jogo is 'Catálogo físico de Country.bin: código, nome pt-BR, sigla e procedência reproduzível.';
comment on table clube_novo.afinidade_tecnico_jogo is 'Códigos físicos 0..7 da afinidade de técnico; rótulo exposto somente quando comprovado.';
comment on column clube_novo.tecnico_jogo.idade is 'Coach.bin bit 231 largura 7; transformação idade=valor+14.';
comment on column clube_novo.tecnico_jogo.codigo_nacionalidade is 'Coach.bin bit 170 largura 8; FK para nacionalidade_jogo.';
comment on column clube_novo.tecnico_jogo.codigo_afinidade is 'Coach.bin bit 187 largura 3; zero é ausência legítima.';

do $$
begin
  if (select count(*) from clube_novo.nacionalidade_jogo) <> 214 then raise exception 'readback: nacionalidades != 214'; end if;
  if (select count(*) from clube_novo.afinidade_tecnico_jogo) <> 8 then raise exception 'readback: afinidades != 8'; end if;
  if (select count(*) from clube_novo.tecnico_jogo where idade is not null) <> 1478 then raise exception 'readback: técnicos com idade != 1478'; end if;
  if (select count(*) from clube_novo.tecnico_jogo where codigo_nacionalidade is not null) <> 1478 then raise exception 'readback: técnicos com nacionalidade != 1478'; end if;
  if (select count(*) from clube_novo.tecnico_jogo where codigo_afinidade is not null) <> 1478 then raise exception 'readback: técnicos com afinidade != 1478'; end if;
  if (select count(*) from clube_novo.tecnico_jogo where codigo_afinidade=0) <> 1456 then raise exception 'readback: afinidade zero != 1456'; end if;
  if exists (select 1 from clube_novo.tecnico_jogo t left join clube_novo.nacionalidade_jogo n on n.codigo_jogo=t.codigo_nacionalidade where t.codigo_nacionalidade is not null and n.codigo_jogo is null) then raise exception 'readback: nacionalidade órfã'; end if;
  if exists (select 1 from clube_novo.tecnico_jogo t left join clube_novo.afinidade_tecnico_jogo a on a.codigo_jogo=t.codigo_afinidade where t.codigo_afinidade is not null and a.codigo_jogo is null) then raise exception 'readback: afinidade órfã'; end if;
  if (select count(*) from clube_novo.tecnico_jogo where fonte_autoritativa<>'dt870_updated' and idade is not null) <> 0 then raise exception 'readback: identidade histórica recebeu campo atual'; end if;
  if not exists (select 1 from clube_novo.tecnico_jogo where id=17601312850052 and idade=44 and codigo_nacionalidade=215 and codigo_afinidade=5) then raise exception 'readback: Capello divergiu'; end if;
  if (select count(*) from clube_novo.mapa_do_jogo where assunto = any(array['tecnico.idade','tecnico.nacionalidade','tecnico.afinidade','nacionalidade.codigo','nacionalidade.nome_pt_br','nacionalidade.sigla','afinidade_tecnico.rotulo.codigo_5'])) <> 7 then raise exception 'readback: mapa granular != 7'; end if;
end $$;
commit;
